-- Seed data for itineraries

on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  duration_days = excluded.duration_days,
  cover_image = excluded.cover_image;

delete from public.itinerary_items
where itinerary_id in (select id from public.itineraries where slug in ('modhera-and-patan-day-trip', 'champaner-and-vadodara-day-trip', 'gir-and-somnath-weekend', 'kutch-mandvi-and-the-rann', 'junagadh-gir-and-somnath', 'heritage-highlights-ahmedabad-to-vadodara', 'saurashtra-and-the-coast', 'heritage-to-the-narmada'));

