insert into public.itineraries (slug, title, description, duration_days, cover_image)
values
  ('modhera-and-patan-day-trip', 'Modhera and Patan Day Trip', 'Two 11th-century Chaulukya monuments in one day: a Sun Temple and a famous stepwell. Best between October and March.', 1, 'destinations/modhera-sun-temple.jpg'),
  ('champaner-and-vadodara-day-trip', 'Champaner and Vadodara Day Trip', 'A Sultanate-era archaeological park in the morning and a grand royal palace later in the day. Best between October and February.', 1, 'destinations/champaner-pavagadh.jpg'),
  ('gir-and-somnath-weekend', 'Gir and Somnath Weekend', 'Asiatic lions on the first day and a seaside pilgrimage temple on the second. Gir is usually closed during the monsoon, so plan for December to March.', 2, 'destinations/gir-national-park.jpg'),
  ('kutch-mandvi-and-the-rann', 'Kutch: Mandvi and the White Rann', 'A historic port town and beach, then the white salt desert. Best from November to February.', 2, 'destinations/rann-of-kutch.jpg'),
  ('junagadh-gir-and-somnath', 'Junagadh, Gir and Somnath', 'A classic Saurashtra route from an ancient fort city, through lion country, to a seaside temple. Best between December and March, when Gir is open.', 3, 'destinations/junagadh-uparkot-fort.jpg'),
  ('heritage-highlights-ahmedabad-to-vadodara', 'Heritage Highlights: Ahmedabad to Vadodara', 'Three days through Gujarat''s best-known heritage: a walled city, two Chaulukya monuments, a Sultanate-era archaeological park and a royal palace. Best between October and February.', 3, 'destinations/ahmedabad-heritage-city.jpg'),
  ('saurashtra-and-the-coast', 'Saurashtra and the Coast', 'Five days from Junagadh to the Gulf of Kutch: a fort city, lions, two great temples and a marine park. Best between December and February.', 5, 'destinations/somnath-temple.jpg'),
  ('heritage-to-the-narmada', 'Heritage to the Narmada', 'Five days from the walled city of Ahmedabad to the Statue of Unity, taking in stepwells, temples, a Sultanate-era city and a palace on the way. Best between October and February.', 5, 'destinations/statue-of-unity.jpg')
insert into public.itinerary_items (itinerary_id, destination_id, day_number, sequence_number, description)
values
  ((select id from public.itineraries where slug = 'modhera-and-patan-day-trip'), (select id from public.destinations where slug = 'modhera-sun-temple'), 1, 1, 'Start with the Sun Temple. Look closely at the carved assembly hall and walk around the stepped tank, the Surya Kund, in the morning light.'),
  ((select id from public.itineraries where slug = 'modhera-and-patan-day-trip'), (select id from public.destinations where slug = 'rani-ki-vav'), 1, 2, 'Continue to Patan and walk down the levels of the stepwell, looking closely at the carved panels. Carry water and wear comfortable shoes.'),
  ((select id from public.itineraries where slug = 'champaner-and-vadodara-day-trip'), (select id from public.destinations where slug = 'champaner-pavagadh'), 1, 1, 'Start early. Walk through the old city''s mosques, gateways and ruins, and climb Pavagadh Hill if time allows. Check whether the ropeway is operating.'),
  ((select id from public.itineraries where slug = 'champaner-and-vadodara-day-trip'), (select id from public.destinations where slug = 'laxmi-vilas-palace'), 1, 2, 'Continue to Vadodara and admire the palace and its grounds. Check the visiting arrangements first, as part of the complex is a private residence.'),
  ((select id from public.itineraries where slug = 'gir-and-somnath-weekend'), (select id from public.destinations where slug = 'gir-national-park'), 1, 1, 'Arrive and take a guided jeep safari through the forest. Safaris usually need advance booking through official channels, so check the current rules.'),
  ((select id from public.itineraries where slug = 'gir-and-somnath-weekend'), (select id from public.destinations where slug = 'somnath-temple'), 2, 1, 'Visit Somnath Temple in the morning, attend the aarti if the timing allows, and walk along the seashore beside the temple.'),
  ((select id from public.itineraries where slug = 'kutch-mandvi-and-the-rann'), (select id from public.destinations where slug = 'mandvi-beach'), 1, 1, 'See the traditional wooden shipbuilding yards and the beach, visit Vijay Vilas Palace if it is open, and stay for the sunset.'),
  ((select id from public.itineraries where slug = 'kutch-mandvi-and-the-rann'), (select id from public.destinations where slug = 'rann-of-kutch'), 2, 1, 'Allow time for the road journey. Watch the sun set over the white salt flats, and check any permit rules near the border and the Rann Utsav dates before you go.'),
  ((select id from public.itineraries where slug = 'junagadh-gir-and-somnath'), (select id from public.destinations where slug = 'junagadh-uparkot-fort'), 1, 1, 'Explore Uparkot Fort, its rock-cut Buddhist caves and its old stepwells, and see Mahabat Maqbara. If time allows, visit Ashoka''s rock edicts near Mount Girnar.'),
  ((select id from public.itineraries where slug = 'junagadh-gir-and-somnath'), (select id from public.destinations where slug = 'gir-national-park'), 2, 1, 'Travel to Sasan Gir and take a guided jeep safari. Visit the Devalia Safari Park if time allows.'),
  ((select id from public.itineraries where slug = 'junagadh-gir-and-somnath'), (select id from public.destinations where slug = 'somnath-temple'), 3, 1, 'Visit Somnath Temple and the seashore beside it, and see the Triveni Sangam nearby.'),
  ((select id from public.itineraries where slug = 'heritage-highlights-ahmedabad-to-vadodara'), (select id from public.destinations where slug = 'ahmedabad-heritage-city'), 1, 1, 'Take a heritage walk through the old city: Bhadra Fort, the Teen Darwaza gateway, Jama Masjid, Sidi Saiyyed Mosque and the pols. Visit Manek Chowk in the evening.'),
  ((select id from public.itineraries where slug = 'heritage-highlights-ahmedabad-to-vadodara'), (select id from public.destinations where slug = 'modhera-sun-temple'), 2, 1, 'Start with the Sun Temple and its stepped tank, which lies on the way to Patan.'),
  ((select id from public.itineraries where slug = 'heritage-highlights-ahmedabad-to-vadodara'), (select id from public.destinations where slug = 'rani-ki-vav'), 2, 2, 'Continue to Patan for the carved stepwell, then return to Ahmedabad.'),
  ((select id from public.itineraries where slug = 'heritage-highlights-ahmedabad-to-vadodara'), (select id from public.destinations where slug = 'champaner-pavagadh'), 3, 1, 'Travel towards Vadodara and visit the Champaner-Pavagadh archaeological park. Start early, as there is a lot of walking.'),
  ((select id from public.itineraries where slug = 'heritage-highlights-ahmedabad-to-vadodara'), (select id from public.destinations where slug = 'laxmi-vilas-palace'), 3, 2, 'Finish in Vadodara at Laxmi Vilas Palace. Check the visiting arrangements beforehand.'),
  ((select id from public.itineraries where slug = 'saurashtra-and-the-coast'), (select id from public.destinations where slug = 'junagadh-uparkot-fort'), 1, 1, 'Explore Uparkot Fort, its caves and stepwells, and the old city. Mount Girnar is nearby if you want a longer day.'),
  ((select id from public.itineraries where slug = 'saurashtra-and-the-coast'), (select id from public.destinations where slug = 'gir-national-park'), 2, 1, 'Take a guided jeep safari in Gir. Book in advance and check that the park is open.'),
  ((select id from public.itineraries where slug = 'saurashtra-and-the-coast'), (select id from public.destinations where slug = 'somnath-temple'), 3, 1, 'Visit Somnath Temple and walk along the seashore. A quieter day to rest before the long drive.'),
  ((select id from public.itineraries where slug = 'saurashtra-and-the-coast'), (select id from public.destinations where slug = 'dwarkadhish-temple'), 4, 1, 'Allow most of the day for the road journey from Somnath. Attend the darshan or aarti at Dwarkadhish Temple and walk to the Gomti Ghat.'),
  ((select id from public.itineraries where slug = 'saurashtra-and-the-coast'), (select id from public.destinations where slug = 'marine-national-park'), 5, 1, 'Travel towards Jamnagar. Visits to the Marine National Park usually need forest department permission and are planned around the tides, so check the rules in advance.'),
  ((select id from public.itineraries where slug = 'heritage-to-the-narmada'), (select id from public.destinations where slug = 'ahmedabad-heritage-city'), 1, 1, 'Take a heritage walk through the old city, and eat at Manek Chowk in the evening.'),
  ((select id from public.itineraries where slug = 'heritage-to-the-narmada'), (select id from public.destinations where slug = 'modhera-sun-temple'), 2, 1, 'Begin with the Sun Temple and its stepped tank.'),
  ((select id from public.itineraries where slug = 'heritage-to-the-narmada'), (select id from public.destinations where slug = 'rani-ki-vav'), 2, 2, 'Continue to the stepwell at Patan, then return towards Ahmedabad.'),
  ((select id from public.itineraries where slug = 'heritage-to-the-narmada'), (select id from public.destinations where slug = 'champaner-pavagadh'), 3, 1, 'Travel towards Vadodara and spend the day at the Champaner-Pavagadh archaeological park.'),
  ((select id from public.itineraries where slug = 'heritage-to-the-narmada'), (select id from public.destinations where slug = 'laxmi-vilas-palace'), 4, 1, 'Visit Laxmi Vilas Palace and its grounds, and see more of Vadodara. Check the visiting arrangements first.'),
  ((select id from public.itineraries where slug = 'heritage-to-the-narmada'), (select id from public.destinations where slug = 'statue-of-unity'), 5, 1, 'Travel to Kevadia for the Statue of Unity and the view of the Narmada river. Check the official website for current opening hours.'),
  ((select id from public.itineraries where slug = 'heritage-to-the-narmada'), (select id from public.destinations where slug = 'zarwani-waterfall'), 5, 2, 'If time and season allow, add Zarwani Waterfall in the same district. It is at its best between July and October.');
